// HasSet applies the HasEdge predicate on the "set" edge.
func HasSet() predicate.LibraryCard {
	return predicate.LibraryCard(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SetTable, SetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSetWith applies the HasEdge predicate on the "set" edge with a given conditions (other predicates).
func HasSetWith(preds ...predicate.LibrarySet) predicate.LibraryCard {
	return predicate.LibraryCard(func(s *sql.Selector) {
		step := newSetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LibraryCard) predicate.LibraryCard {
	return predicate.LibraryCard(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LibraryCard) predicate.LibraryCard {
	return predicate.LibraryCard(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LibraryCard) predicate.LibraryCard {
	return predicate.LibraryCard(sql.NotPredicates(p))
}
